from common import L, mc, num, multi, order, card, S_SEE, S_OS, S_KHAN, S_HENZE, S_HARD

M1 = {"id": "wkeit.m1", "level": 1, "title": "Zufall und Wahrscheinlichkeit", "desc": "Was eine Wahrscheinlichkeit ist, wie man sie berechnet und schätzt.", "lessons": [
 L("wkeit.m1.l1", "Was ist eine Wahrscheinlichkeit?", 5, [
  "Eine Wahrscheinlichkeit ist eine Zahl zwischen 0 und 1, die angibt, wie sicher ein Ereignis eintritt. 0 heißt: kommt nie vor. 1 heißt: kommt sicher vor. Dazwischen liegt alles Ungewisse. Statt 0,25 sagt man oft 25 %.",
  "## Die Laplace-Regel",
  "Sind alle Ergebnisse gleich wahrscheinlich, gilt: Wahrscheinlichkeit = Anzahl der günstigen Ergebnisse geteilt durch Anzahl aller möglichen Ergebnisse. Beim Würfel ist die Chance auf eine 6 also 1 von 6, das sind etwa 16,7 %. Die Chance auf eine gerade Zahl ist 3 von 6 = 1/2.",
  "## Ergebnis, Ereignis, Ergebnismenge",
  "Ein Ergebnis ist ein einzelner Ausgang, etwa „Würfel zeigt 4“. Die Ergebnismenge Ω (Omega) enthält alle möglichen Ergebnisse, beim Würfel {1, 2, 3, 4, 5, 6}. Ein Ereignis ist eine Teilmenge davon, zum Beispiel „gerade Zahl“ = {2, 4, 6}.",
  "## Wann die Regel nicht passt",
  "Die Laplace-Regel gilt nur, wenn alle Ergebnisse wirklich gleich wahrscheinlich sind. „Morgen regnet es oder nicht“ sind zwei Ergebnisse, aber nicht jeweils 50 %. Dann braucht man Erfahrungswerte oder ein Modell."],
  ["Wahrscheinlichkeit: Zahl von 0 (nie) bis 1 (sicher).", "Laplace: günstige ÷ mögliche Ergebnisse, nur bei gleich wahrscheinlichen Ergebnissen.", "Ereignis = Teilmenge der Ergebnismenge Ω."],
  [S_SEE, S_HENZE],
  [card("Wahrscheinlichkeit", "Zahl zwischen 0 und 1 (oder 0 bis 100 %), die angibt, wie sicher ein Ereignis eintritt."),
   card("Laplace-Regel", "P(E) = günstige Ergebnisse ÷ mögliche Ergebnisse, wenn alle Ergebnisse gleich wahrscheinlich sind."),
   card("Ergebnismenge Ω", "Menge aller möglichen Ergebnisse eines Zufallsexperiments."),
   card("Ereignis", "Teilmenge der Ergebnismenge, z. B. „gerade Zahl“ beim Würfeln.")],
  [mc("Wie groß ist die Wahrscheinlichkeit, mit einem fairen Würfel eine Zahl größer als 4 zu würfeln?", ["1/3", "1/2", "1/6", "2/3"], 0, "Günstig sind 5 und 6, also 2 von 6 Ergebnissen = 1/3."),
   num("In einer Tüte sind 3 rote und 7 blaue Kugeln. Wie groß ist die Wahrscheinlichkeit, blind eine rote zu ziehen (in Prozent)?", 30, "%", 0.5, "3 günstige von 10 möglichen Kugeln = 3/10 = 30 %."),
   mc("Welche Aussage ist falsch?", ["Eine Wahrscheinlichkeit kann 1,2 sein", "0,5 entspricht 50 %", "1 bedeutet: tritt sicher ein", "0 bedeutet: tritt nie ein"], 0, "Wahrscheinlichkeiten liegen immer zwischen 0 und 1."),
   mc("Warum darf man für „Morgen regnet es“ nicht einfach 1/2 annehmen?", ["Die zwei Ausgänge sind nicht gleich wahrscheinlich", "Weil es mehr als zwei Ausgänge gibt", "Weil Wetter gar nicht zufällig ist", "Weil 1/2 keine Wahrscheinlichkeit ist"], 0, "Laplace setzt gleich wahrscheinliche Ergebnisse voraus. Beim Wetter hängt es von der Lage ab.")]),
 L("wkeit.m1.l2", "Häufigkeit und das Gesetz der großen Zahlen", 5, [
  "Oft kennt man die Wahrscheinlichkeit nicht vorher. Dann probiert man es aus: Die relative Häufigkeit ist die Anzahl der Treffer geteilt durch die Anzahl der Versuche. Wirft man eine Reißzwecke 200-mal und landet sie 120-mal auf dem Rücken, ist die relative Häufigkeit 120/200 = 0,6.",
  "## Das Gesetz der großen Zahlen",
  "Bei wenigen Versuchen schwankt die relative Häufigkeit stark. Je mehr Versuche, desto näher liegt sie in der Regel an der tatsächlichen Wahrscheinlichkeit. Probiere es unten aus: Nach 10 Münzwürfen sind 70 % Kopf völlig normal, nach 10.000 Würfen liegt der Anteil sehr nah an 50 %.",
  "## Was das Gesetz nicht sagt",
  "Es sagt nicht, dass sich „Pech ausgleichen muss“. Die Münze hat kein Gedächtnis. Nach fünfmal Kopf ist Zahl nicht wahrscheinlicher. Der Anteil nähert sich 50 %, weil die neuen Würfe die alten Ausreißer verdünnen, nicht weil sie sie ausgleichen."],
  ["Relative Häufigkeit = Treffer ÷ Versuche.", "Bei vielen Versuchen nähert sie sich der Wahrscheinlichkeit.", "Zufall hat kein Gedächtnis: Ausreißer werden verdünnt, nicht ausgeglichen."],
  [S_SEE, S_OS],
  [card("Relative Häufigkeit", "Anteil der Treffer an allen Versuchen: Treffer ÷ Versuche."),
   card("Gesetz der großen Zahlen", "Bei vielen unabhängigen Wiederholungen nähert sich die relative Häufigkeit der Wahrscheinlichkeit an."),
   card("Spielerfehlschluss", "Irrtum, dass nach einer Serie das Gegenteil „fällig“ sei. Unabhängige Ereignisse haben kein Gedächtnis.")],
  [num("Ein Basketballer trifft 45 von 60 Freiwürfen. Wie hoch ist die relative Trefferhäufigkeit (in Prozent)?", 75, "%", 0.5, "45 ÷ 60 = 0,75 = 75 %."),
   mc("Eine Münze zeigte sechsmal Kopf. Wie wahrscheinlich ist Kopf beim siebten Wurf?", ["50 %", "Unter 50 %", "Über 50 %", "Genau 1/7"], 0, "Die Würfe sind unabhängig. Jeder Wurf hat wieder 50 %."),
   mc("Was beschreibt das Gesetz der großen Zahlen?", ["Der Anteil nähert sich der Wahrscheinlichkeit", "Nach Pech kommt zwingend Glück", "Seltene Ereignisse passieren nie", "Ab 100 Würfen ist alles exakt"], 0, "Bei vielen Wiederholungen liegt die relative Häufigkeit nah an der Wahrscheinlichkeit, aber nie garantiert exakt."),
   mc("Warum sind 7 von 10 Kopf bei einer fairen Münze kein Grund zur Sorge?", ["Bei wenigen Würfen schwankt der Anteil stark", "Weil die Münze sich erst einspielen muss", "Weil Kopf schwerer ist", "Weil 70 % fast 50 % sind"], 0, "Kleine Stichproben schwanken stark. Erst bei vielen Würfen wird der Anteil stabil.")],
  figs=[{"after": 3, "w": "coin", "cap": "Simuliere Münzwürfe und beobachte, wie sich der Anteil von Kopf einpendelt."}]),
 L("wkeit.m1.l3", "Gegenereignis und „mindestens einmal“", 5, [
  "Das Gegenereignis von E heißt „nicht E“. Zusammen sind sie sicher, also gilt P(nicht E) = 1 − P(E). Die Chance, keine 6 zu würfeln, ist 1 − 1/6 = 5/6.",
  "## Der Trick für „mindestens einmal“",
  "Fragen nach „mindestens einmal“ rechnet man fast immer über das Gegenteil, nämlich „kein einziges Mal“. Beispiel: Wie wahrscheinlich ist mindestens eine 6 bei vier Würfen? Keine 6 in einem Wurf: 5/6. Keine 6 in vier Würfen: (5/6)⁴ ≈ 0,482. Also mindestens eine 6: 1 − 0,482 ≈ 0,518, gut 51,8 %.",
  "## Warum das wichtig ist",
  "Kleine Risiken summieren sich. Hat ein Bauteil pro Jahr eine Ausfallchance von 2 %, fällt es in 10 Jahren mit 1 − 0,98¹⁰ ≈ 18 % mindestens einmal aus, vorausgesetzt, die Jahre sind unabhängig. Das unterschätzt man im Bauch fast immer.",
  "## Typischer Fehler",
  "Man darf die Einzelchancen nicht einfach addieren: Viermal 1/6 wären 4/6 ≈ 67 %, das ist falsch. Bei sechs Würfen käme man sogar auf 100 %, und trotzdem kann man sechsmal keine 6 würfeln."],
  ["P(nicht E) = 1 − P(E).", "„Mindestens einmal“ = 1 − „keinmal“.", "Einzelchancen nicht addieren, sondern das Gegenteil multiplizieren."],
  [S_HENZE, S_KHAN],
  [card("Gegenereignis", "„Nicht E“. Es gilt P(nicht E) = 1 − P(E)."),
   card("Mindestens einmal", "Über das Gegenteil rechnen: 1 − P(keinmal). Bei unabhängigen Versuchen: 1 − (1 − p)ⁿ.")],
  [num("Wie groß ist die Wahrscheinlichkeit, bei zwei Würfen mindestens eine 6 zu würfeln (in Prozent, gerundet)?", 30.6, "%", 0.6, "1 − (5/6)² = 1 − 25/36 = 11/36 ≈ 30,6 %."),
   mc("Ein Medikament hat bei 1 % der Einnahmen eine Nebenwirkung. Wie groß ist das Risiko bei 50 unabhängigen Einnahmen, sie mindestens einmal zu erleben?", ["Etwa 39 %", "Genau 50 %", "Etwa 1 %", "Etwa 99 %"], 0, "1 − 0,99⁵⁰ ≈ 1 − 0,605 = 0,395, also etwa 39 %."),
   mc("Warum ist „4 × 1/6 = 67 %“ für „mindestens eine 6 in vier Würfen“ falsch?", ["Fälle mit mehreren Sechsen werden doppelt gezählt", "Weil Würfel kein Gedächtnis haben", "Weil 1/6 falsch ist", "Weil man durch 4 teilen muss"], 0, "Addieren zählt Würfe mit zwei oder mehr Sechsen mehrfach. Richtig ist 1 − (5/6)⁴ ≈ 52 %."),
   num("Die Chance, eine Prüfung nicht zu bestehen, ist 0,15. Wie groß ist die Chance, sie zu bestehen (in Prozent)?", 85, "%", 0.5, "1 − 0,15 = 0,85.")]),
 L("wkeit.m1.l4", "Prozent, Bruch, Chancen (Odds)", 4, [
  "Dieselbe Wahrscheinlichkeit lässt sich verschieden schreiben: 1/4 = 0,25 = 25 %. Wer sicher umrechnet, versteht Nachrichten, Studien und Wettquoten besser.",
  "## Chancen (Odds)",
  "Im Englischen und bei Wetten sind „Odds“ verbreitet: das Verhältnis von günstig zu ungünstig. Bei p = 0,2 stehen die Chancen 1 : 4 (eins zu vier), denn auf einen Treffer kommen vier Nicht-Treffer. Umgekehrt: Chancen von a : b entsprechen der Wahrscheinlichkeit a ÷ (a + b).",
  "## Natürliche Häufigkeiten",
  "Menschen verstehen „3 von 1.000“ meist besser als „0,3 %“. Darum rechnen gute Risikoangaben in ganzen Personen. Das hilft später bei bedingten Wahrscheinlichkeiten enorm."],
  ["1/4 = 0,25 = 25 %.", "Odds a : b ↔ Wahrscheinlichkeit a ÷ (a + b).", "„x von 1.000“ ist oft verständlicher als Prozent."],
  [S_HENZE, S_HARD],
  [card("Odds (Chancen)", "Verhältnis günstig : ungünstig. Bei p = 0,2 → 1 : 4."),
   card("Natürliche Häufigkeit", "Angabe in ganzen Fällen, z. B. „3 von 1.000“, statt in Prozent.")],
  [num("Die Chancen stehen 1 : 3. Wie groß ist die Wahrscheinlichkeit (in Prozent)?", 25, "%", 0.5, "1 ÷ (1 + 3) = 0,25."),
   mc("Wie schreibt man 0,4 % als natürliche Häufigkeit?", ["4 von 1.000", "4 von 100", "40 von 1.000", "1 von 4"], 0, "0,4 % = 0,004 = 4 von 1.000."),
   mc("Wie stehen die Chancen bei einer Wahrscheinlichkeit von 75 %?", ["3 : 1", "1 : 3", "3 : 4", "4 : 3"], 0, "75 günstig zu 25 ungünstig = 3 : 1.")])
]}

M2 = {"id": "wkeit.m2", "level": 1, "title": "Zählen ohne Abzählen", "desc": "Kombinatorik: wie viele Möglichkeiten es gibt, ohne alle aufzuschreiben.", "lessons": [
 L("wkeit.m2.l1", "Die Produktregel", 4, [
  "Viele Wahrscheinlichkeiten scheitern am Zählen. Die wichtigste Regel ist einfach: Wählt man nacheinander aus mehreren Stufen, multipliziert man die Anzahl der Möglichkeiten.",
  "## Beispiele",
  "3 Hosen und 4 Shirts ergeben 3 · 4 = 12 Outfits. Eine vierstellige PIN aus den Ziffern 0 bis 9 hat 10 · 10 · 10 · 10 = 10.000 Möglichkeiten. Ein Passwort aus 8 Kleinbuchstaben (26 Buchstaben) hat 26⁸ ≈ 209 Milliarden Möglichkeiten.",
  "## Warum lange Passwörter sicherer sind",
  "Jede zusätzliche Stelle multipliziert die Anzahl. Eine Stelle mehr aus 26 Zeichen macht das Durchprobieren 26-mal aufwändiger. Deshalb ist Länge wichtiger als ein einzelnes Sonderzeichen."],
  ["Mehrere Stufen: Möglichkeiten multiplizieren.", "PIN mit 4 Ziffern: 10⁴ = 10.000.", "Jede Stelle mehr vervielfacht die Möglichkeiten."],
  [S_HENZE, S_KHAN],
  [card("Produktregel", "Bei mehreren unabhängigen Auswahlstufen werden die Anzahlen multipliziert.")],
  [num("Ein Menü hat 3 Vorspeisen, 5 Hauptgerichte und 2 Desserts. Wie viele Menüs gibt es?", 30, "", 0, "3 · 5 · 2 = 30."),
   num("Wie viele dreistellige Zahlencodes (000 bis 999) gibt es?", 1000, "", 0, "10 · 10 · 10 = 1.000."),
   mc("Wie viel mehr Kombinationen hat eine 6-stellige PIN gegenüber einer 4-stelligen?", ["100-mal so viele", "2-mal so viele", "50 % mehr", "20-mal so viele"], 0, "10⁶ ÷ 10⁴ = 10² = 100.")]),
 L("wkeit.m2.l2", "Reihenfolgen: Permutationen", 5, [
  "Wie viele Reihenfolgen gibt es für n verschiedene Dinge? Für den ersten Platz gibt es n Kandidaten, für den zweiten noch n − 1 und so weiter. Das ergibt n · (n − 1) · … · 1 = n! (gesprochen „n Fakultät“).",
  "## Fakultät wächst rasant",
  "3! = 6, 5! = 120, 10! = 3.628.800. Schon 13 Personen können sich auf über 6 Milliarden Arten in eine Reihe stellen.",
  "## Nur einige Plätze besetzen",
  "Werden nur k von n Plätzen vergeben und die Reihenfolge zählt, rechnet man n · (n − 1) · … (k Faktoren). Beispiel: Gold, Silber und Bronze unter 10 Läufern: 10 · 9 · 8 = 720 Möglichkeiten."],
  ["n verschiedene Dinge: n! Reihenfolgen.", "k von n Plätzen mit Reihenfolge: n · (n − 1) · … (k Faktoren).", "Fakultäten wachsen extrem schnell."],
  [S_HENZE, S_OS],
  [card("Fakultät n!", "n · (n − 1) · … · 1. Anzahl der Reihenfolgen von n verschiedenen Dingen. 0! = 1."),
   card("Permutation", "Eine Anordnung (Reihenfolge) von Dingen.")],
  [num("Auf wie viele Arten können sich 5 Personen in eine Reihe stellen?", 120, "", 0, "5! = 120."),
   num("Ein Verein wählt aus 8 Mitgliedern Vorsitz, Stellvertretung und Kasse (verschiedene Ämter). Wie viele Möglichkeiten?", 336, "", 0, "8 · 7 · 6 = 336."),
   mc("Was ist 0! ?", ["1", "0", "Nicht definiert", "Unendlich"], 0, "Per Definition ist 0! = 1; es gibt genau eine Art, nichts anzuordnen.")]),
 L("wkeit.m2.l3", "Auswahl ohne Reihenfolge: n über k", 6, [
  "Beim Lotto zählt nur, welche Zahlen man hat, nicht in welcher Reihenfolge sie gezogen wurden. Dann teilt man die Anzahl mit Reihenfolge durch die k! Reihenfolgen jeder Auswahl. Das ergibt den Binomialkoeffizienten „n über k“ = n! ÷ (k! · (n − k)!).",
  "## Beispiel Lotto 6 aus 49",
  "49 · 48 · 47 · 46 · 45 · 44 Möglichkeiten mit Reihenfolge, geteilt durch 6! = 720, ergibt 13.983.816 Tipps. Die Chance auf 6 Richtige ist also etwa 1 zu 14 Millionen; mit Superzahl (eine von 10) etwa 1 zu 140 Millionen.",
  "## Kleines Beispiel zum Nachrechnen",
  "Aus 5 Freunden 2 für eine Fahrgemeinschaft auswählen: 5 · 4 ÷ 2 = 10 Möglichkeiten. Prüfe es durch Aufschreiben: AB, AC, AD, AE, BC, BD, BE, CD, CE, DE."],
  ["Ohne Reihenfolge: n über k = n! ÷ (k! · (n − k)!).", "Lotto 6 aus 49: 13.983.816 Möglichkeiten.", "Mit Reihenfolge zählt man k! mal zu viel."],
  [S_HENZE, {"n": "LOTTO 6aus49 (Deutscher Lotto- und Totoblock)", "u": "https://www.lotto.de/"}],
  [card("Binomialkoeffizient (n über k)", "Anzahl der Möglichkeiten, k von n Dingen ohne Reihenfolge auszuwählen: n! ÷ (k! · (n − k)!)."),
   card("Lotto 6 aus 49", "13.983.816 mögliche Tipps; mit Superzahl etwa 1 zu 140 Millionen für den Jackpot.")],
  [num("Wie viele Möglichkeiten gibt es, aus 6 Personen ein Team aus 3 zu bilden?", 20, "", 0, "6 · 5 · 4 ÷ 3! = 120 ÷ 6 = 20."),
   mc("Wann braucht man „n über k“ statt der Produktregel mit Reihenfolge?", ["Wenn die Reihenfolge keine Rolle spielt", "Wenn Zurücklegen erlaubt ist", "Wenn n kleiner als k ist", "Wenn alle Dinge gleich sind"], 0, "Bei der Auswahl ohne Reihenfolge teilt man durch die k! Reihenfolgen."),
   num("Ein Pokerblatt hat 5 Karten aus 52. Wie viele Blätter gibt es (Zahl ohne Punkte)?", 2598960, "", 0, "52 über 5 = 2.598.960.")]),
 L("wkeit.m2.l4", "Das Geburtstagsparadoxon", 5, [
  "Wie viele Menschen braucht man, damit mit über 50 % zwei am selben Tag Geburtstag haben? Die meisten schätzen 183. Die Antwort ist 23.",
  "## Warum so wenige?",
  "Es geht nicht um deinen Geburtstag, sondern um irgendein Paar. Bei 23 Personen gibt es 23 · 22 ÷ 2 = 253 Paare. Man rechnet wieder über das Gegenteil: Alle haben verschiedene Geburtstage mit (365/365) · (364/365) · … · (343/365) ≈ 0,493. Also ein gemeinsamer Geburtstag mit etwa 50,7 % (Schaltjahre vernachlässigt).",
  "## Bedeutung im Alltag",
  "Das Prinzip erklärt, warum „unglaubliche Zufälle“ häufig sind: Es gibt so viele Möglichkeiten für irgendein Zusammentreffen, dass irgendeines fast immer passiert. In der IT nutzt man es zur Abschätzung, wann Kollisionen bei Prüfsummen auftreten."],
  ["Bei 23 Personen über 50 %, bei 50 Personen etwa 97 %.", "Es zählen alle Paare, nicht nur die eigenen Paare.", "Über das Gegenteil rechnen: alle verschieden."],
  [S_SEE, S_HENZE],
  [card("Geburtstagsparadoxon", "Schon ab 23 Personen haben mit über 50 % zwei denselben Geburtstag, weil es sehr viele Paare gibt.")],
  [num("Wie viele Paare lassen sich aus 10 Personen bilden?", 45, "", 0, "10 · 9 ÷ 2 = 45."),
   mc("Warum unterschätzen wir die Chance gemeinsamer Geburtstage?", ["Wir denken an uns statt an alle Paare", "Weil Geburtstage im Sommer häufiger sind", "Weil das Jahr 366 Tage hat", "Weil Zwillinge mitzählen"], 0, "Die Zahl der Paare wächst viel schneller als die Zahl der Personen."),
   mc("Mit welcher Wahrscheinlichkeit teilen sich in einer Gruppe von 50 Personen mindestens zwei den Geburtstag?", ["Etwa 97 %", "Etwa 14 %", "Etwa 50 %", "Genau 100 %"], 0, "Rechnung über das Gegenteil ergibt etwa 97 %.")],
  figs=[{"after": 2, "w": "birthday", "cap": "Verändere die Gruppengröße und sieh, wie schnell die Wahrscheinlichkeit steigt."}])
]}
